// FASE 2 horizontal — resuelve que ICP Pack usar. Por defecto casino-escolar (compatibilidad).
const incoming = $input.first()?.json ?? {};
const icpPackId = incoming.icp_pack_id || null;
const icpPackSlug = incoming.icp_pack_slug || 'atacama-labs';
const filter = icpPackId ? `id=eq.${icpPackId}` : `slug=eq.${icpPackSlug}`;
return [{json:{
  limit: incoming.limit,
  account_ids: incoming.account_ids,
  school_ids: incoming.school_ids,
  icp_pack_url: `https://uwquwjmiofixzugttals.supabase.co/rest/v1/icp_packs?${filter}&select=id,slug,status,discovery,research_vocabulary&limit=1`
}}];

const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
const row = Array.isArray(body) ? body[0] : body;
if (status < 200 || status >= 300 || !row || !row.id) {
  throw new Error(`ICP Pack no encontrado o inaccesible (HTTP ${status || 'unknown'}). Revisa que exista un pack activo con ese id/slug en icp_packs.`);
}
if (row.status !== 'active') {
  throw new Error(`ICP Pack '${row.slug}' esta en estado '${row.status}', no 'active'. No se puede ejecutar un ICP que no esta activo (evita correr configuraciones en preparacion por accidente).`);
}
const init = $('Init ICP Config').first().json;
return [{json:{
  icp_pack_id: row.id,
  icp_pack_slug: row.slug,
  discovery: row.discovery || {},
  research_vocabulary: row.research_vocabulary || {},
  limit: init.limit,
  account_ids: init.account_ids,
  school_ids: init.school_ids
}}];

const cfg = $('Init Configuration').first().json;
const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
if (status < 200 || status >= 300) {
  throw new Error(`OpenClaw preflight failed: HTTP ${status || 'unknown'}. Verify the OpenClaw Header Auth credential and the internal proxy.`);
}
const models = Array.isArray(body?.data) ? body.data.map(x => x?.id).filter(Boolean) : [];
if (!models.includes(cfg.openclaw_model)) {
  throw new Error(`Configured Prospector target '${cfg.openclaw_model}' was not returned by GET /v1/models. Available: ${models.join(', ') || '(none)'}`);
}
return [{json:{ok:true, models, selected_model:cfg.openclaw_model}}];

const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
if (status < 200 || status >= 300) {
  throw new Error(`Supabase schools read failed: HTTP ${status || 'unknown'}`);
}
const rows = Array.isArray(body) ? body : [];
if (!rows.length) return [{json:{_no_work:true, reason:'No pending schools matched this run'}}];

// Fase 6 — round-robin por territory_id: reparte el cupo real entre comunas en vez de
// agotar la mas antigua primero. Con accountIds explicitos (test manual) no hace falta repartir.
const realLimit = Number($('Init Configuration').first().json.request.limit) || rows.length;
const groups = new Map();
for (const r of rows) {
  const key = r.territory_id || 'none';
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(r);
}
const groupArrays = [...groups.values()];
const selected = [];
let i = 0;
while (selected.length < realLimit && groupArrays.some(g => g.length)) {
  const g = groupArrays[i % groupArrays.length];
  if (g.length) selected.push(g.shift());
  i++;
}

return selected.map(s => ({json:{...s, _no_work:false}}));

const school = $('Loop Over Schools').item.json;
const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? [];
const claimed = status >= 200 && status < 300 && Array.isArray(body) && body.length === 1;
return [{json:{school, claimed, claim_http_status:status, claim_reason:claimed ? null : `Could not claim pending row (HTTP ${status || 'unknown'} / rows ${Array.isArray(body)?body.length:'?'})`}}];

const cfg = $('Init Configuration').first().json;
const school = $json.school;
const website = typeof school.website === 'string' ? school.website.trim() : '';
return [{json:{school, crawl4ai_should_run:Boolean(cfg.crawl4ai_enabled && website), verification_started_at:new Date().toISOString()}}];

// 02 - Research Engine FINAL — EnBandeja (FASE 2: horizontal, lee accounts + ICP Pack)
// Runtime endpoints below were verified from n8n on 2026-08-13; generalizado 2026-09-01.
// DO NOT paste tokens/API keys/passwords in this Code node. Use n8n credentials.
const incoming = $input.first()?.json ?? {};
const icp = $('Parse ICP Pack').first().json;

const CONFIG = {
  supabase_url: 'https://uwquwjmiofixzugttals.supabase.co',

  crawl4ai_enabled: true,
  crawl4ai_base_url: 'http://crawl4ai:11235',

  openclaw_base_url: 'http://openclaw-gateway:18790',
  openclaw_model: 'openclaw/prospector',

  default_limit: 1,
  manual_test_account_ids: [], // Atacama: sin fallback de prueba fijo; requiere account_ids o limit explicito, o no hace nada
  max_limit: 25,

  crawl4ai_markdown_max_chars: 16000,
  crawl4ai_links_max: 30,

  researcher: 'prospector/openclaw',
  workflow_revision: 'atacama-02-research-2026-09-15',
  icp_pack_id: icp.icp_pack_id,
  icp_pack_slug: icp.icp_pack_slug,
};

const requestedLimit = Number(incoming.limit ?? CONFIG.default_limit);
const limit = Number.isFinite(requestedLimit)
  ? Math.max(1, Math.min(CONFIG.max_limit, Math.trunc(requestedLimit)))
  : CONFIG.default_limit;

const manualRun = incoming.limit === undefined && incoming.account_ids === undefined && incoming.school_ids === undefined;
let accountIds = incoming.account_ids ?? incoming.school_ids ?? (manualRun ? CONFIG.manual_test_account_ids : []);
if (typeof accountIds === 'string') {
  try { accountIds = JSON.parse(accountIds); }
  catch { accountIds = accountIds.split(',').map(s => s.trim()).filter(Boolean); }
}
if (!Array.isArray(accountIds)) accountIds = [];
accountIds = [...new Set(accountIds.map(String).filter(Boolean))].slice(0, CONFIG.max_limit);

for (const [key, value] of Object.entries({
  openclaw_base_url: CONFIG.openclaw_base_url,
  openclaw_model: CONFIG.openclaw_model,
  crawl4ai_base_url: CONFIG.crawl4ai_base_url,
})) {
  if (!value || String(value).startsWith('__VERIFY_')) {
    throw new Error(`CONFIG REQUIRED: ${key} is missing or unverified.`);
  }
}

const select = 'id,legacy_school_id,legacy_operator_id,account_type,territory_id,name,normalized_name,region,commune,city,address,website,domain,phone,google_maps_url,google_place_id,source,source_url,research_status,created_at';
// Fase 6 — pedimos un pool mas grande que el limit real para poder repartir por territorio (round-robin)
// en 'Build School Items', en vez de agotar el territorio mas antiguo antes de tocar los demas.
const fetchPoolSize = accountIds.length ? limit : Math.min(CONFIG.max_limit * 12, 1000);
const filters = [`research_status=eq.pending`, `icp_pack_id=eq.${CONFIG.icp_pack_id}`, `select=${select}`, `order=territory_id.asc,created_at.asc`, `limit=${fetchPoolSize}`];
if (accountIds.length) filters.push(`id=in.(${accountIds.join(',')})`);

return [{json: {
  ...CONFIG,
  request: { limit, account_ids: accountIds },
  accounts_url: `${CONFIG.supabase_url}/rest/v1/accounts?${filters.join('&')}`
}}];

const cfg = $('Init Configuration').first().json;
const vocab = ($('Parse ICP Pack').first().json.research_vocabulary) || {};
const factors = Array.isArray(vocab.factors) && vocab.factors.length
  ? vocab.factors
  : ['pain', 'budget_proxy', 'volume', 'automation', 'access', 'urgency', 'fit'];
const promptContext = vocab.prompt_context || 'Empresa B2B. Evalua evidencia de dolor operativo, capacidad de inversion, volumen, potencial de automatizacion, acceso a decisor, urgencia y encaje.';
const ctx = $('Build Research Context').item.json;
const account = ctx.school;
const c4 = $input.first().json ?? {};

const asUrl = value => {
  if (typeof value !== 'string' || !value.trim()) return null;
  try {
    const u = new URL(value.trim(), account.website || undefined);
    return /^https?:$/.test(u.protocol) ? u.toString() : null;
  } catch { return null; }
};
const markdownText = value => {
  if (typeof value === 'string') return value;
  if (!value || typeof value !== 'object') return null;
  for (const key of ['fit_markdown', 'raw_markdown', 'markdown_with_citations', 'markdown']) {
    if (typeof value[key] === 'string' && value[key].trim()) return value[key];
  }
  return null;
};
const normalizeLinks = value => {
  const raw = [];
  if (Array.isArray(value)) raw.push(...value);
  else if (value && typeof value === 'object') {
    for (const key of ['internal', 'external']) if (Array.isArray(value[key])) raw.push(...value[key]);
  }
  const out = []; const seen = new Set();
  for (const item of raw) {
    const candidate = typeof item === 'string' ? item : (item?.href || item?.url || null);
    const url = asUrl(candidate);
    if (!url || seen.has(url)) continue;
    seen.add(url); out.push(url);
    if (out.length >= Number(cfg.crawl4ai_links_max || 30)) break;
  }
  return out;
};

let crawl4ai = { used: false, ok: false, source_url: account.website || null, markdown: null, links: [], error: null, http_status: null };
if (!c4.crawl4ai_skipped) {
  const status = Number(c4.statusCode ?? 0);
  const body = c4.body ?? c4;
  const results = Array.isArray(body?.results) ? body.results : (Array.isArray(body?.result?.results) ? body.result.results : []);
  const result = results[0] ?? null;
  crawl4ai.used = true;
  crawl4ai.http_status = status || null;
  crawl4ai.ok = status >= 200 && status < 300 && body?.success !== false && result !== null && result?.success !== false;
  crawl4ai.source_url = asUrl(result?.url) || asUrl(result?.metadata?.url) || account.website || null;
  const md = markdownText(result?.markdown);
  crawl4ai.markdown = md ? md.slice(0, Number(cfg.crawl4ai_markdown_max_chars || 16000)) : null;
  crawl4ai.links = normalizeLinks(result?.links);
  if (!crawl4ai.ok) {
    crawl4ai.error = body?.task_id && !result
      ? `Crawl4AI returned async task_id ${String(body.task_id).slice(0, 120)} instead of synchronous results`
      : `HTTP ${status || 'unknown'}${body?.error ? ': ' + String(body.error).slice(0, 500) : ''}`;
  }
}

const system = `Eres el agente de investigacion de Atacama Labs. Tu unica tarea es reunir evidencia VERIFICABLE (con URL y fecha reales) sobre una empresa real, para calificarla segun un modelo de 7 factores -- NUNCA inventes datos ni afirmes algo sin evidencia real.

Contexto del ICP: ${promptContext}

Factores a evaluar (usa EXACTAMENTE estas claves en tu respuesta, ninguna otra): ${factors.join(', ')}.
Para cada factor donde encuentres evidencia (no es obligatorio tener las 7), reporta un nivel:
  0 = sin evidencia o no encaja
  1 = senal indirecta plausible (ej: mencion general, tamano de empresa, industria)
  2 = evidencia concreta y directa (ej: declaracion explicita, dato verificable)
No inventes dolor ni intencion de compra. Si no hay evidencia real de un factor, simplemente no lo incluyas (no fuerces nivel 0 con una nota inventada).

Responde EXCLUSIVAMENTE en JSON valido con esta forma exacta:
{
  "evidence": [
    {
      "id": "e1",
      "factor": "<una de las claves de factores>",
      "level": 0 | 1 | 2,
      "finding": "resumen de una linea de lo encontrado",
      "evidence_text": "cita o descripcion textual de la evidencia real",
      "source_url": "https://...",
      "source_date": "YYYY-MM-DD o null si no se puede determinar",
      "certainty": "observed" | "inferred"
    }
  ],
  "summary": "resumen breve en 1-2 frases de lo mas relevante encontrado"
}
No agregues texto fuera del JSON. No uses markdown ni bloques de codigo.`;

const userParts = [
  `Empresa: ${account.name}`,
  account.website ? `Sitio web: ${account.website}` : null,
  account.region || account.city ? `Ubicacion: ${[account.city, account.region].filter(Boolean).join(', ')}` : null,
  account.source_url ? `Fuente de descubrimiento: ${account.source_url}` : null,
  crawl4ai.ok && crawl4ai.markdown ? `\n--- Contenido del sitio web (crawl real) ---\n${crawl4ai.markdown}` : '\n(No se pudo crawlear el sitio web o no existe; basate en lo que puedas verificar por otras fuentes publicas si tu agente tiene esa capacidad, o reporta evidence vacio.)',
  crawl4ai.links.length ? `\nEnlaces internos detectados: ${crawl4ai.links.slice(0, 10).join(', ')}` : null,
].filter(Boolean).join('\n');

return [{
  json: {
    ...ctx,
    crawl4ai,
    system_prompt: system,
    user_prompt: userParts,
  },
}];

const base = $('Build Prospector Prompt').item.json;
const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
const errors = [];

if (status < 200 || status >= 300) errors.push(`OpenClaw HTTP ${status || 'unknown'}`);

let content = body?.choices?.[0]?.message?.content;
if (typeof content !== 'string') errors.push('OpenClaw response missing choices[0].message.content');

let parsed = null;
if (typeof content === 'string') {
  let cleaned = content.trim().replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/\s*```$/, '').trim();
  const first = cleaned.indexOf('{'), last = cleaned.lastIndexOf('}');
  if (first >= 0 && last > first) cleaned = cleaned.slice(first, last + 1);
  try { parsed = JSON.parse(cleaned); } catch (e) { errors.push(`Invalid JSON from Prospector: ${e.message}`); }
}
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) parsed = {};

const allowedFactors = new Set(['pain', 'budget_proxy', 'volume', 'automation', 'access', 'urgency', 'fit']);
const text = (v, max = 1400) => (typeof v === 'string' && v.trim() ? v.trim().slice(0, max) : null);
const httpUrl = u => {
  const s = text(u, 2000);
  return s && /^https?:\/\/[^\s]+$/i.test(s) ? s : null;
};

const evidence = [];
const seenIds = new Set();
for (const raw of (Array.isArray(parsed.evidence) ? parsed.evidence : [])) {
  const factor = allowedFactors.has(raw?.factor) ? raw.factor : null;
  const level = [0, 1, 2].includes(Number(raw?.level)) ? Number(raw.level) : null;
  const finding = text(raw?.finding, 1400);
  const evidence_text = text(raw?.evidence_text, 1800);
  const source_url = httpUrl(raw?.source_url);
  if (!factor || level === null || !finding || !evidence_text || !source_url) continue;

  let id = String(raw.id || `e${evidence.length + 1}`).trim();
  if (!id || seenIds.has(id)) id = `e${evidence.length + 1}`;
  seenIds.add(id);

  const source_date = /^\d{4}-\d{2}-\d{2}$/.test(String(raw.source_date || '')) ? String(raw.source_date) : null;
  const certainty = raw.certainty === 'observed' ? 'observed' : 'inferred';

  evidence.push({ id, factor, level, finding, evidence_text, source_url, source_date, certainty });
}

const valid = errors.length === 0;
return [{
  json: {
    ...base,
    valid,
    parse_errors: errors,
    evidence,
    summary: text(parsed.summary, 500),
    resolution: valid ? (evidence.length ? 'evidence_found' : 'no_public_evidence') : 'invalid',
  },
}];

const s = $('Parse Research Result').item.json;
const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
const errs = [...(s.persistence_errors || [])];

let existingKeys = new Set();
if (status >= 200 && status < 300 && Array.isArray(body)) {
  existingKeys = new Set(body.map(r => [r.research_type, String(r.source_url || '').trim().toLowerCase(), String(r.finding || '').trim().toLowerCase()].join('|')));
} else if (status !== 0) {
  errs.push(`Fetch existing research failed: HTTP ${status}`);
}

const nowIso = new Date().toISOString();
const newRows = [];
for (const e of (s.evidence || [])) {
  const research_type = 'factor:' + e.factor;
  const key = [research_type, String(e.source_url).trim().toLowerCase(), String(e.finding).trim().toLowerCase()].join('|');
  if (existingKeys.has(key)) continue;
  newRows.push({
    account_id: s.school.id,
    research_type,
    finding: e.finding,
    evidence_text: e.evidence_text,
    source_url: e.source_url,
    source_title: null,
    source_date: e.source_date,
    verified_at: nowIso,
    confidence: e.level / 2,
    is_current: true,
    researcher: 'prospector/openclaw',
    raw_metadata: { factor: e.factor, level: e.level, certainty: e.certainty, evidence_id: e.id },
  });
}

return [{ json: { ...s, persistence_errors: errs, new_research_rows: newRows } }];

const s = $json;
const sb = $('Init Configuration').first().json.supabase_url;
const aid = s.school.id;
return [{ json: { ...s, contacts: [], existing_contacts_url: `${sb}/rest/v1/contacts?account_id=eq.${aid}&select=id,account_id,email,phone,whatsapp&limit=1000` } }];

const s=$('Prepare Contacts').item.json; const res=$input.first().json??{}; const status=Number(res.statusCode??0); const body=res.body??res; const errs=[...(s.persistence_errors||[])];
const normPhone=v=>String(v||'').replace(/\D/g,''); const normEmail=v=>String(v||'').trim().toLowerCase();
let rows=[];
if(status>=200&&status<300&&Array.isArray(body)){
  const emails=new Set(body.map(x=>normEmail(x.email)).filter(Boolean));
  const phones=new Set(body.flatMap(x=>[normPhone(x.phone),normPhone(x.whatsapp)]).filter(Boolean));
  rows=(s.contacts||[]).filter(c=>{
    const e=normEmail(c.email), p=normPhone(c.phone||c.whatsapp);
    if(e&&emails.has(e)) return false;
    if(p&&phones.has(p)) return false;
    return true;
  }).map(c=>({account_id:s.school.id, name:c.name||null, job_title:c.job_title||null, email:c.email||null, phone:c.phone||null, whatsapp:c.whatsapp||null, source_url:c.source_url||null, confidence:c.confidence||null, contact_status:'found', metadata:{}}));
} else if (status!==0) { errs.push(`Fetch existing contacts failed: HTTP ${status}`); }
return [{json:{...s, persistence_errors:errs, new_contacts:rows}}];

const s = $json;
const errs = [...(s.persistence_errors || [])];
let status = 'recheck';
let reason = null;
const evidenceCount = (s.new_research_rows || []).length + (s.evidence || []).length;

if (errs.length) {
  status = 'error';
  reason = errs.join('; ');
} else if (s.resolution === 'evidence_found') {
  status = 'complete';
  reason = `Research con evidencia (${evidenceCount} hallazgo(s))`;
} else if (s.resolution === 'no_public_evidence') {
  status = 'complete';
  reason = 'Sin evidencia publica encontrada (research igualmente completado, sin inventar)';
} else {
  status = 'recheck';
  reason = 'Respuesta del agente invalida o incompleta';
}

return [{
  json: {
    ...s,
    final_research_status: status,
    final_reason: reason,
    account_patch: { research_status: status, updated_at: new Date().toISOString() },
  },
}];

if ($json.iteration_result) return [{ json: $json }];
let s = null;
try { s = $('Prepare Final Account Update').first().json; } catch {}
if (!s) return [{ json: { iteration_result: { status: 'error', reason: 'Could not recover final state' } } }];

const res = $input.first().json ?? {};
const http = Number(res.statusCode ?? 0);
const body = res.body ?? [];
const updateOk = http >= 200 && http < 300 && Array.isArray(body) && body.length === 1;
const status = updateOk ? s.final_research_status : 'error';
const reason = updateOk ? s.final_reason : `Final account update failed: HTTP ${http}`;

return [{
  json: {
    iteration_result: {
      account_id: s.school.id,
      account_name: s.school.name,
      status,
      reason,
      research_inserted: (s.new_research_rows || []).length,
      contacts_inserted: (s.new_contacts || []).length,
      evidence_factors: [...new Set((s.evidence || []).map(e => e.factor))],
    },
  },
}];

let items=[]; try{items=$items('Build Iteration Result').map(x=>x.json.iteration_result).filter(Boolean);}catch{}
const count=k=>items.filter(x=>x.status===k).length;
return [{json:{
  workflow:'Atacama Labs - 02 Research',
  revision:$('Init Configuration').first().json.workflow_revision,
  processed:items.length, complete:count('complete'), recheck:count('recheck'), error:count('error'), skipped:count('skipped'),
  research_rows_inserted: items.reduce((a,x)=>a+(x.research_inserted||0),0),
  contacts_inserted: items.reduce((a,x)=>a+(x.contacts_inserted||0),0),
  results: items,
}}];
